"""Export actual current route proposals and retained source geometry. Not Unity admission or rendering."""
import measure_city_rebirth_04o as base
base.CODE=r'''
using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Text;using System.Text.Json;using NeonSyndicate;using UnityEngine;
public sealed class Input {public string Version;public List<VenueDefinition04C> Venues=new List<VenueDefinition04C>();}
public static class Probe {
static float[] P(Vector3 p){return new[]{p.x,p.y,p.z};}
static object Write(string name,MeshBuilder mesh){StringBuilder text=new StringBuilder();foreach(Vector3 p in mesh.Vertices)text.AppendFormat(System.Globalization.CultureInfo.InvariantCulture,"v {0:R} {1:R} {2:R}\n",p.x,p.y,p.z);for(int s=0;s<mesh.SubmeshCount;s++){IReadOnlyList<int> t=mesh.Triangles(s);for(int i=0;i<t.Count;i+=3)text.AppendLine("f "+(t[i]+1)+" "+(t[i+1]+1)+" "+(t[i+2]+1));}File.WriteAllText(name+".obj",text.ToString());return new{name,vertices=mesh.VertexCount};}
public static void Main(string[] args){List<string> errors=new List<string>();Input input=QuestJson.Read<Input>(File.ReadAllText(args[0]),args[0],errors,null);if(errors.Count!=0)throw new Exception(string.Join(";",errors));
CityLayout l=new CityLayout(61724);l.Generate();List<VenueBinding04C> venues=InhabitedCityBindings04C.Select(l,new VenueCatalog04C{Version=input.Version,Venues=input.Venues.ToArray()});if(!l.ApplyProfile04O(CityRevision04O.GothicCivicH5,venues))throw new Exception("Original revision rejected.");
List<object> parts=new List<object>(),geometry=new List<object>();foreach(VenueBinding04C v in venues){bool civic=GothicCivicH5.Replaces(v.Definition.Id);foreach(ArtPlacementH2 p in civic?GothicCivicH5.Plan(v):GothicHeartH3.ServicePlan(v))parts.Add(new{owner=v.Definition.Id,model=p.Model,position=P(InhabitedCityBindings04C.LocalToWorld(v.Origin,v.Yaw,p.Position)),yaw=p.Yaw+v.Yaw,scale=P(p.Scale)});
if(civic || GothicHeartH3.Replaces(v.Definition.Id)){MeshBuilder local=new MeshBuilder(1),mineral=new MeshBuilder(1),world=new MeshBuilder(1);if(civic)GothicCivicH5.Structure(local,v,mineral);else GothicHeartH3.Structure(local,v);local.Append(mineral);world.Append(local);for(int i=0;i<world.Vertices.Count;i++)world.Vertices[i]=InhabitedCityBindings04C.LocalToWorld(v.Origin,v.Yaw,world.Vertices[i]);geometry.Add(Write("retained-service-"+v.Definition.Id,world));}}
foreach(ArtPlacementH2 p in GothicHeartH3.CourtPlan(l).Concat(GothicHeartH3.RegionalPlan(l)))parts.Add(new{owner="court and regional",model=p.Model,position=P(p.Position),yaw=p.Yaw,scale=P(p.Scale)});
List<object> buildings=new List<object>();foreach(Block block in l.Blocks)foreach(Lot lot in block.Lots)foreach(Building b in lot.Buildings){if(MathUtil.FlatDistance(b.Footprint.Center(0),l.RealmCourt04OB)>650)continue;bool eligible=HeartPlanFR01.Eligible(l,b);buildings.Add(new{seed=b.Seed,family=b.GothicFamily04OB,rect=new[]{b.Footprint.X0,b.Footprint.Z0,b.Footprint.X1,b.Footprint.Z1},height=b.Height,eligible,poi=lot.PoiName});if(b.GothicFamily04OB>0){MeshBuilder stone=new MeshBuilder(1),trim=new MeshBuilder(1),crystal=new MeshBuilder(1);GothicRealmGeometry04OB.Family(stone,trim,crystal,b,true);stone.Append(trim);stone.Append(crystal);geometry.Add(Write("retained-family-"+b.Seed,stone));}}
Vector3 gate;float yaw;bool found=HeartPlanFR01.Gate(l,out gate,out yaw);List<object> candidates=new List<object>();for(int i=0;i<HeartPlanFR01.GateCandidates;i++){Vector3 p;float y;string reason;bool ok=HeartPlanFR01.GateCandidate(l,i,out p,out y,out reason);candidates.Add(new{index=i,source_admitted=ok,position=P(p),yaw=y,reason});}
List<object> sides=new List<object>();foreach(HeartSideFR01 p in HeartPlanFR01.StreetSides(l))sides.Add(new{module=p.Module,position=P(p.Position),yaw=p.Yaw,radius=p.Radius,source_clear=HeartPlanFR01.Clear(l,p.Position,p.Radius),source_admitted=HeartPlanFR01.Clear(l,p.Position,p.Radius)&&(!found||HeartPlanFR01.OutsideGate(p.Position,p.Radius,gate,yaw))});
List<object> legacyCandidates=new List<object>(),legacySides=new List<object>();foreach(RealmRoute04OB r in l.RealmRoutes04OB)if(r.Id=="home-court"){Vector3 aa=r.Points[r.Points.Count-2],bb=r.Points[r.Points.Count-1],f=MathUtil.Flat(bb-aa).normalized,side=MathUtil.RightOf(f);for(int i=0;i<9;i++){Vector3 at=Vector3.Lerp(aa,bb,.2f+i*.075f);legacyCandidates.Add(new{index=i,position=P(at),yaw=MathUtil.YawOf(f),source_admitted=HeartPlanFR01.Clear(l,at-side*22,3.4f)&&HeartPlanFR01.Clear(l,at+side*22,3.4f)});}}
Action<string,Vector3,float,float> priorSide=(module,at,turn,radius)=>legacySides.Add(new{module,position=P(at),yaw=turn,radius,source_clear=HeartPlanFR01.Clear(l,at,radius)});
foreach(int sign in new[]{-1,1}){for(int i=0;i<3;i++)priorSide(i%2==0?"HeartRootCourt":"HeartIvyRuin",l.RealmCourt04OB+new Vector3(sign*(34+i*3),0,(i-1)*20),sign*20,3);for(int i=0;i<4;i++)priorSide(i%2==0?"HeartArcade":"HeartBlindBay",l.RealmCourt04OB+new Vector3(sign*15,0,12+i*7),sign*90,3);}
foreach(RealmRoute04OB r in l.RealmRoutes04OB)if(r.Id=="sanctuary-approach")priorSide("HeartFocus",r.Points[r.Points.Count-1]+Vector3.right*11,0,2);
Console.WriteLine(JsonSerializer.Serialize(new{scope="Actual compiled revision-10 source, original H3/H5 parts and structural meshes. Native physical and trigger probes NOT RUN. Background ordinary building envelopes are approximate silhouettes only.",seed=61724,revision=10,court=P(l.RealmCourt04OB),gate=new{ready=found,position=P(gate),yaw},candidates,sides,legacy_candidates=legacyCandidates,legacy_sides=legacySides,buildings,routes=l.RealmRoutes04OB.Select(r=>new{id=r.Id,width=r.Width,points=r.Points.Select(p=>P(p)).ToArray()}),art_parts=parts,geometry,native_unity="NOT RUN"}));}}
'''
if __name__=='__main__':base.main()
